import { useState, useEffect } from "react";
import { useLocation, useParams } from "wouter";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { customFetch } from "@workspace/api-client-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  X, ArrowLeft, CalendarDays, ExternalLink, Ban, Plus, Phone, ChevronLeft, ChevronRight, Tag,
} from "lucide-react";
import { SportPill } from "@/components/sport-icon";
import { OwnerLayout } from "@/components/owner-layout";
import { useToast } from "@/hooks/use-toast";

const BASE_URL = import.meta.env.BASE_URL.replace(/\/$/, "");
const API_URL = `${BASE_URL}/api`;

const STATUS_COLORS: Record<string, string> = {
  confirmed: "bg-emerald-500/10 text-emerald-600 border-emerald-500/20",
  pending: "bg-amber-500/10 text-amber-600 border-amber-500/20",
  awaiting_players: "bg-blue-500/10 text-blue-600 border-blue-500/20",
  cancelled: "bg-destructive/10 text-destructive border-destructive/20",
  rejected: "bg-destructive/10 text-destructive border-destructive/20",
};
const STATUS_LT: Record<string, string> = {
  confirmed: "Patvirtinta", pending: "Laukiama", awaiting_players: "Laukia žaidėjų", cancelled: "Atšaukta", rejected: "Atmesta",
};

function todayStr() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function isoDate(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function prevDay(s: string): string { const d = new Date(s + "T12:00:00"); d.setDate(d.getDate() - 1); return isoDate(d); }
function nextDay(s: string): string { const d = new Date(s + "T12:00:00"); d.setDate(d.getDate() + 1); return isoDate(d); }
function mondayOf(s: string): string {
  const d = new Date(s + "T12:00:00");
  const dow = d.getDay();
  d.setDate(d.getDate() - (dow === 0 ? 6 : dow - 1));
  return isoDate(d);
}
function addDays(s: string, n: number): string {
  const d = new Date(s + "T12:00:00");
  d.setDate(d.getDate() + n);
  return isoDate(d);
}
function weekDays(s: string): string[] {
  const d = new Date(s + "T12:00:00");
  const dow = d.getDay();
  const mon = new Date(d);
  mon.setDate(d.getDate() - (dow === 0 ? 6 : dow - 1));
  return Array.from({ length: 7 }, (_, i) => { const x = new Date(mon); x.setDate(mon.getDate() + i); return isoDate(x); });
}

function getWeekDates() {
  const today = new Date();
  const day = today.getDay();
  const diff = today.getDate() - day + (day === 0 ? -6 : 1);
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(today);
    d.setDate(diff + i);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  });
}

const DAY_NAMES = ["Pir", "Ant", "Tre", "Ket", "Pen", "Šeš", "Sek"];

function fmtDate(d: string) {
  const [, m, day] = d.split("-");
  return `${day}.${m}`;
}

function fmtPrice(n: number) {
  return n.toLocaleString("lt-LT", { style: "currency", currency: "EUR" });
}

