1	import { useEffect, useState } from "react";
2	import { useLocation } from "wouter";
3	import { useQueryClient } from "@tanstack/react-query";
4	import { Layout } from "@/components/layout";
5	import {
6	  CheckCircle2, Calendar, Clock, ArrowRight, Loader2, XCircle,
7	  Users, Copy, Check, Globe, Share2, ExternalLink, CreditCard, UserPlus,
8	} from "lucide-react";
9	import { Button } from "@/components/ui/button";
10	import { format } from "date-fns";
11	import { useSafeAuth } from "@/lib/safeAuth";
12	import { SignUp } from "@clerk/react";
13	
14	const clerkPubKey = import.meta.env.VITE_CLERK_PUBLISHABLE_KEY as string | undefined;
15	
16	const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
17	const API = `${BASE}/api`;
18	
19	interface BookingInfo {
20	  id: number;
21	  courtId: number;
22	  courtName?: string;
23	  date: string;
24	  startTime: string;
25	  endTime: string;
26	  totalPrice: number;
27	  customerName: string;
28	  customerEmail?: string;
29	  status: string;
30	}
31	
32	interface SplitConfirmInfo {
33	  bookingId: number;
34	  gameId: number | null;
35	  shareToken: string | null;
36	  pricePerSlot: number;
37	  totalSlots: number;
38	  paidSlots: number;
39	  totalPrice: number;
40	  date: string;
41	  startTime: string;
42	  endTime: string;
43	  sport: string | null;
44	  isPublic: boolean;
45	  courtId: number | null;
46	  courtName: string | null;
47	  courtImageUrl: string | null;
48	}
49	
50	function formatBookingDate(value: string): string {
51	  const date = new Date(value);
52	  return Number.isNaN(date.getTime()) ? value : format(date, "yyyy-MM-dd");
53	}
54	
55	function CopyButton({ text }: { text: string }) {
56	  const [copied, setCopied] = useState(false);
57	  const copy = () => {
58	    navigator.clipboard.writeText(text).then(() => {
59	      setCopied(true);
60	      setTimeout(() => setCopied(false), 2000);
61	    });
62	  };
63	  return (
64	    <button
65	      onClick={copy}
66	      className="flex items-center gap-1 text-xs text-primary hover:text-primary/80 transition-colors ml-auto shrink-0"
67	    >
68	      {copied ? <Check className="w-3.5 h-3.5" /> : <Copy className="w-3.5 h-3.5" />}
69	      {copied ? "Nukopijuota!" : "Kopijuoti"}
70	    </button>
71	  );
72	}
73	
74	function ShareButtons({ url, title }: { url: string; title: string }) {
75	  const [copied, setCopied] = useState(false);
76	
77	  const handleNativeShare = async () => {
78	    if (navigator.share) {
79	      try {
80	        await navigator.share({ title, url });
81	      } catch {
82	        // user cancelled or API not supported
83	      }
84	    }
85	  };
86	
87	  const handleCopy = () => {
88	    navigator.clipboard.writeText(url).then(() => {
89	      setCopied(true);
90	      setTimeout(() => setCopied(false), 2000);
91	    });
92	  };
93	
94	  const waUrl = `https://wa.me/?text=${encodeURIComponent(`${title}\n${url}`)}`;
95	  const tgUrl = `https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(title)}`;
96	
97	  return (
98	    <div className="space-y-2">
99	      <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Dalintis</p>
100	      <div className="flex gap-2 flex-wrap">
101	        {typeof navigator !== "undefined" && "share" in navigator && (
102	          <Button size="sm" variant="outline" className="gap-1.5" onClick={handleNativeShare}>
103	            <Share2 className="w-3.5 h-3.5" />
104	            Dalintis
105	          </Button>
106	        )}
107	        <a
108	          href={waUrl}
109	          target="_blank"
110	          rel="noopener noreferrer"
111	          className="inline-flex items-center gap-1.5 h-9 px-3 rounded-md border border-border text-sm font-medium text-foreground hover:bg-muted transition-colors"
112	        >
113	          <span className="text-base leading-none">💬</span>
114	          WhatsApp
115	        </a>
116	        <a
117	          href={tgUrl}
118	          target="_blank"
119	          rel="noopener noreferrer"
120	          className="inline-flex items-center gap-1.5 h-9 px-3 rounded-md border border-border text-sm font-medium text-foreground hover:bg-muted transition-colors"
121	        >
122	          <span className="text-base leading-none">✈️</span>
123	          Telegram
124	        </a>
125	        <Button size="sm" variant="outline" className="gap-1.5" onClick={handleCopy}>
126	          {copied ? <Check className="w-3.5 h-3.5 text-green-500" /> : <Copy className="w-3.5 h-3.5" />}
127	          {copied ? "Nukopijuota!" : "Kopijuoti"}
128	        </Button>
129	      </div>
130	    </div>
131	  );
132	}
133	
134	const signUpAppearance: React.ComponentProps<typeof SignUp>["appearance"] = {
135	  variables: {
136	    colorPrimary: "#84cc16",
137	    colorBackground: "transparent",
138	    colorText: "var(--foreground)",
139	    colorInputBackground: "var(--muted)",
140	    colorInputText: "var(--foreground)",
141	    borderRadius: "0.75rem",
142	    fontFamily: "inherit",
143	    fontSize: "0.875rem",
144	  },
145	  elements: {
146	    rootBox: "w-full",
147	    card: "shadow-none border-0 p-0 bg-transparent w-full",
148	    header: "hidden",
149	    headerTitle: "hidden",
150	    headerSubtitle: "hidden",
151	    socialButtonsBlockButton:
152	      "border border-border bg-muted hover:bg-muted/70 text-foreground rounded-xl h-10 font-medium transition-colors",
153	    dividerLine: "bg-border",
154	    dividerText: "text-muted-foreground text-xs",
155	    formFieldLabel: "text-sm font-medium text-foreground text-left block",
156	    formFieldInput:
157	      "bg-muted border border-border rounded-xl h-10 text-foreground placeholder:text-muted-foreground focus:border-lime-500",
158	    formButtonPrimary:
159	      "bg-lime-500 hover:bg-lime-600 text-black font-semibold rounded-xl h-10 transition-colors",
160	    footer: { display: "none" },
161	    footerAction: { display: "none" },
162	    formFieldSuccessText: "text-lime-600",
163	    formFieldErrorText: "text-destructive text-xs",
164	    alertText: "text-sm",
165	  },
166	};
167	
168	function ClaimProfileSection({ email }: { email: string }) {
169	  const [expanded, setExpanded] = useState(false);
170	
171	  return (
172	    <div className="border border-primary/30 rounded-xl bg-primary/5 text-left overflow-hidden">
173	      <button
174	        type="button"
175	        onClick={() => setExpanded(v => !v)}
176	        className="w-full flex items-center gap-3 px-4 py-3.5 hover:bg-primary/10 transition-colors"
177	      >
178	        <div className="w-8 h-8 rounded-full bg-primary/20 flex items-center justify-center shrink-0">
179	          <UserPlus className="w-4 h-4 text-primary" />
180	        </div>
181	        <div className="flex-1 min-w-0 text-left">
182	          <p className="text-sm font-semibold text-foreground">Sukurkite paskyrą</p>
183	          <p className="text-xs text-muted-foreground truncate">
184	            Sutaupykite laiką kitą kartą – duomenys bus užpildyti automatiškai
185	          </p>
186	        </div>
187	        <span className="text-xs font-medium text-primary shrink-0">
188	          {expanded ? "Uždaryti" : "Registruotis"}
189	        </span>
190	      </button>
191	
192	      {expanded && (
193	        <div className="px-4 pb-5 pt-1 border-t border-primary/20">
194	          <p className="text-xs text-muted-foreground mb-4 leading-relaxed">
195	            Mokėjimas sėkmingas! Sukurkite paskyrą, kad nereikėtų vesti duomenų kitą kartą
196	            ir galėtumėte sekti visas savo rezervacijas vienoje vietoje.
197	          </p>
198	          <SignUp
199	            routing="hash"
200	            fallbackRedirectUrl={`${BASE}/bookings`}
201	            initialValues={{ emailAddress: email }}
202	            appearance={signUpAppearance}
203	          />
204	        </div>
205	      )}
206	    </div>
207	  );
208	}
209	
210	export default function BookingConfirmed() {
211	  const [, setLocation] = useLocation();
212	  const queryClient = useQueryClient();
213	  const { isLoaded: authLoaded, isSignedIn } = useSafeAuth();
214	  const params = new URLSearchParams(window.location.search);
215	  const bookingId = params.get("id");
216	  const sessionId = params.get("session_id");
217	  const isSplit = params.get("split") === "1";
218	
219	  const [booking, setBooking] = useState<BookingInfo | null>(null);
220	  const [splitInfo, setSplitInfo] = useState<SplitConfirmInfo | null>(null);
221	  const [state, setState] = useState<"loading" | "success" | "error">("loading");
222	
223	  useEffect(() => {
224	    try { sessionStorage.removeItem("stripeCancel_pending"); } catch { /* ignore */ }
225	    const confirm = async () => {
226	      try {
227	        if (isSplit && sessionId) {
228	          const r = await fetch(`${API}/payments/confirm-split`, {
229	            method: "POST",
230	            headers: { "Content-Type": "application/json" },
231	            body: JSON.stringify({ sessionId }),
232	          });
233	          if (!r.ok) throw new Error("Split payment confirmation failed");
234	          const data: SplitConfirmInfo = await r.json();
235	          setSplitInfo(data);
236	        } else if (sessionId && !sessionId.startsWith("mock_")) {
237	          const r = await fetch(`${API}/payments/confirm`, {
238	            method: "POST",
239	            headers: { "Content-Type": "application/json" },
240	            body: JSON.stringify({ sessionId }),
241	          });
242	          if (!r.ok) throw new Error("Payment confirmation failed");
243	          const data = await r.json();
244	          setBooking(data);
245	        } else if (bookingId) {
246	          const r = await fetch(`${API}/bookings/${bookingId}`);
247	          if (r.ok) {
248	            const data = await r.json();
249	            setBooking({ ...data, totalPrice: Number(data.totalPrice ?? 0) });
250	          }
251	        }
252	        await Promise.all([
253	          queryClient.invalidateQueries({ queryKey: ["/api/bookings"] }),
254	          queryClient.invalidateQueries({ queryKey: ["court-activity"] }),
255	          queryClient.invalidateQueries({ queryKey: ["open-matches"] }),
256	          queryClient.invalidateQueries({ predicate: (q) => {
257	            const k = q.queryKey?.[0];
258	            return typeof k === "string" && k.includes("/availability");
259	          } }),
260	        ]);
261	        setState("success");
262	      } catch {
263	        setState("error");
264	      }
265	    };
266	    confirm();
267	  }, []);
268	
269	  const shareUrl = splitInfo?.shareToken
270	    ? `${window.location.origin}${BASE}/join/${splitInfo.shareToken}`
271	    : null;
272	
273	  const courtPageUrl = splitInfo?.courtId
274	    ? `${BASE}/courts/${splitInfo.courtId}`
275	    : booking?.courtId
276	      ? `${BASE}/courts/${booking.courtId}`
277	      : null;
278	
279	  return (
280	    <Layout>
281	      <div className="container mx-auto flex items-center justify-center min-h-[70vh] px-4 py-8">
282	        <div className="max-w-md w-full bg-card border rounded-2xl p-8 text-center shadow-xl space-y-6">
283	
284	          {state === "loading" && (
285	            <>
286	              <div className="flex items-center justify-center">
287	                <div className="w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center">
288	                  <Loader2 className="w-12 h-12 text-primary animate-spin" />
289	                </div>
290	              </div>
291	              <div>
292	                <h1 className="text-2xl font-bold mb-2">Apdorojamas mokėjimas…</h1>
293	                <p className="text-muted-foreground text-sm">Prašome palaukti</p>
294	              </div>
295	            </>
296	          )}
297	
298	          {state === "error" && (
299	            <>
300	              <div className="flex items-center justify-center">
301	                <div className="w-20 h-20 rounded-full bg-destructive/10 flex items-center justify-center">
302	                  <XCircle className="w-12 h-12 text-destructive" />
303	                </div>
304	              </div>
305	              <div>
306	                <h1 className="text-2xl font-bold mb-2">Mokėjimas nepavyko</h1>
307	                <p className="text-muted-foreground text-sm">Bandykite dar kartą arba susisiekite su mumis.</p>
308	              </div>
309	              <Button onClick={() => setLocation("/courts")} className="w-full">
310	                Grįžti į aikštelių sąrašą
311	              </Button>
312	            </>
313	          )}
314	
315	          {state === "success" && splitInfo && (
316	            <>
317	              <div className="flex items-center justify-center">
318	                <div className="w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center">
319	                  <CheckCircle2 className="w-12 h-12 text-primary" />
320	                </div>
321	              </div>
322	
323	              <div>
324	                <h1 className="text-2xl font-bold mb-2">Žaidimas sukurtas!</h1>
325	                <p className="text-muted-foreground text-sm leading-relaxed">
326	                  Sumokėjote savo dalį (€{splitInfo.pricePerSlot.toFixed(2)}). Pakviesk žaidėjus ir padalinkite kortą.
327	                </p>
328	              </div>
329	
330	              {/* Court info (clickable) */}
331	              {splitInfo.courtName && (
332	                <button
333	                  type="button"
334	                  onClick={() => courtPageUrl && setLocation(courtPageUrl)}
335	                  className="w-full text-left bg-muted/40 hover:bg-muted/70 border border-border hover:border-primary/40 rounded-xl overflow-hidden transition-all group"
336	                >
337	                  {splitInfo.courtImageUrl && (
338	                    <div className="h-24 overflow-hidden">
339	                      <img
340	                        src={splitInfo.courtImageUrl.startsWith("http") ? splitInfo.courtImageUrl : `${BASE}/${splitInfo.courtImageUrl}`}
341	                        alt={splitInfo.courtName}
342	                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
343	                      />
344	                    </div>
345	                  )}
346	                  <div className="px-4 py-3 flex items-center justify-between">
347	                    <div className="flex items-center gap-2">
348	                      <span className="text-lg">🏟️</span>
349	                      <span className="font-semibold text-sm group-hover:text-primary transition-colors">{splitInfo.courtName}</span>
350	                    </div>
351	                    <ExternalLink className="w-3.5 h-3.5 text-muted-foreground group-hover:text-primary transition-colors" />
352	                  </div>
353	                </button>
354	              )}
355	
356	              {/* Date / time summary */}
357	              <div className="bg-muted/40 rounded-xl p-4 flex flex-col gap-2.5 text-sm text-left">
358	                <div className="flex items-center gap-2 text-muted-foreground">
359	                  <Calendar className="w-4 h-4 shrink-0" />
360	                  <span>{formatBookingDate(splitInfo.date)}</span>
361	                </div>
362	                <div className="flex items-center gap-2 text-muted-foreground">
363	                  <Clock className="w-4 h-4 shrink-0" />
364	                  <span>{splitInfo.startTime} – {splitInfo.endTime}</span>
365	                </div>
366	              </div>
367	
368	              {/* Pricing breakdown */}
369	              <div className="bg-muted/30 rounded-xl p-4 text-left space-y-2">
370	                <div className="flex items-center justify-between text-sm">
371	                  <span className="flex items-center gap-1.5 text-muted-foreground">
372	                    <CreditCard className="w-4 h-4" />
373	                    Jūsų dalis (1/{splitInfo.totalSlots})
374	                  </span>
375	                  <span className="font-bold text-primary text-base">€{splitInfo.pricePerSlot.toFixed(2)}</span>
376	                </div>
377	                <div className="flex items-center justify-between text-sm border-t border-border pt-2">
378	                  <span className="text-muted-foreground">Visa rezervacijos kaina</span>
379	                  <span className="font-semibold">€{splitInfo.totalPrice.toFixed(2)}</span>
380	                </div>
381	                <div className="flex items-center justify-between text-sm">
382	                  <span className="text-muted-foreground">Liko surinkti iš kitų</span>
383	                  <span className="font-semibold text-orange-500 dark:text-orange-400">
384	                    €{Math.max(0, splitInfo.totalPrice - splitInfo.pricePerSlot).toFixed(2)}
385	                  </span>
386	                </div>
387	              </div>
388	
389	              {/* Player slots progress */}
390	              <div className="bg-muted/30 rounded-xl p-4 text-left space-y-3">
391	                <div className="flex items-center justify-between text-sm">
392	                  <span className="flex items-center gap-1.5 font-medium">
393	                    <Users className="w-4 h-4 text-primary" />
394	                    Žaidėjai
395	                  </span>
396	                  <span className="font-bold">{splitInfo.paidSlots}/{splitInfo.totalSlots} apmokėjo</span>
397	                </div>
