import { Separator } from "@/components/ui/separator";
import { format } from "date-fns";
import { lt } from "date-fns/locale";

const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
const API = `${BASE}/api`;

interface BookingDetail {
  id: number;
  courtId: number;
  courtName?: string;
  courtSport?: string;
  facilityName?: string;
  courtAddress?: string;
  courtCity?: string;
  customerName: string;
  customerEmail: string;
  customerPhone?: string | null;
  date: string;
  startTime: string;
  endTime: string;
  totalPrice: number;
  status: "pending" | "confirmed" | "cancelled" | "awaiting_players";
  stripeSessionId?: string | null;
  createdAt: string;
  isSplit?: boolean;
  totalSlots?: number;
  pricePerSlot?: number;
  splitInviteToken?: string | null;
}

interface SplitParticipant {
  userId: string;
  userName: string | null;
  userEmail: string | null;
  paymentStatus: string;
  joinedAt: string;
}

interface SplitStatus {
  bookingId: number;
  gameId: number | null;
  bookingStatus: string;
  totalSlots: number;
  pricePerSlot: number;
  totalPrice: number;
  shareToken: string | null;
  participants: SplitParticipant[];
}

interface CourtDetail {
  id: number;
  name: string;
  address: string;
  city: string;
  phone?: string | null;
  ownerEmail?: string | null;
  imageUrl?: string | null;
  type: string;
}

function formatDate(value: string): string {
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? value : format(d, "yyyy-MM-dd");
}

function formatDateLong(value: string): string {
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? value : format(d, "EEEE, yyyy-MM-dd", { locale: lt });
}

function StatusBadge({ status }: { status: string }) {
  switch (status) {
    case "confirmed":
      return <Badge className="bg-green-500 text-white"><CheckCircle2 className="w-3 h-3 mr-1" />Patvirtinta</Badge>;
    case "pending":
      return <Badge variant="secondary" className="bg-yellow-500/20 text-yellow-700 dark:text-yellow-400"><Clock className="w-3 h-3 mr-1" />Laukiama</Badge>;
    case "awaiting_players":
      return <Badge variant="secondary" className="bg-blue-500/20 text-blue-700 dark:text-blue-400"><Users className="w-3 h-3 mr-1" />Laukiama žaidėjų</Badge>;
    case "cancelled":
      return <Badge variant="destructive"><XCircle className="w-3 h-3 mr-1" />Atšaukta</Badge>;
    default:
      return <Badge variant="outline">{status}</Badge>;
  }
}

export default function BookingDetail() {
  const { id } = useParams<{ id: string }>();
  const [, setLocation] = useLocation();
  const [booking, setBooking] = useState<BookingDetail | null>(null);
  const [court, setCourt] = useState<CourtDetail | null>(null);
  const [splitStatus, setSplitStatus] = useState<SplitStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    const load = async () => {
      try {
        const bookingRes = await fetch(`${API}/bookings/${id}`);

            )}
            {email && (
              <div className="px-4 py-3 flex items-center gap-3">
                <Mail className="w-4 h-4 text-muted-foreground shrink-0" />
                <a href={`mailto:${email}`} className="text-sm hover:text-primary transition-colors truncate">{email}</a>
              </div>
            )}
          </div>
        )}

        {/* Calendar */}
        <div className="flex gap-3">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" className="flex-1">
                <Calendar className="w-4 h-4 mr-2" />
                Pridėti į kalendorių
                <ChevronDown className="w-4 h-4 ml-2" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem onClick={() => {
                const date = booking.date.split("T")[0].replace(/-/g, "");
                const start = date + "T" + booking.startTime.slice(0, 5).replace(":", "") + "00";
                const end = date + "T" + booking.endTime.slice(0, 5).replace(":", "") + "00";
                const sportLabel = getSportLabel(booking.courtSport);
                const courtLabel = booking.courtName ?? "Kortas";
                const title = booking.facilityName
                  ? `${sportLabel} – ${courtLabel}, ${booking.facilityName}`
                  : `${sportLabel} – ${courtLabel}`;
                const addressParts = [
                  booking.courtAddress,
                  booking.courtCity,
                  "Lietuva",
                ].filter(Boolean);
                const location = addressParts.join(", ");
                const siteUrl = "https://korts.lt";
                const bookingUrl = `${siteUrl}/bookings/${booking.id}`;
                const details = [
                  `📅 Rezervacija #${booking.id}`,
                  `🏟 Aikštelė: ${courtLabel}`,
                  booking.facilityName ? `🏢 Objektas: ${booking.facilityName}` : null,
                  `⚽ Sportas: ${sportLabel}`,
                  `💶 Kaina: ${Number(booking.totalPrice).toFixed(2)} €`,
                  `🔗 Peržiūrėti: ${bookingUrl}`,
                ].filter(Boolean).join("\n");
                const url =
                  `https://calendar.google.com/calendar/render?action=TEMPLATE` +
                  `&text=${encodeURIComponent(title)}` +
                  `&dates=${start}/${end}` +
                  `&ctz=Europe%2FVilnius` +
                  `&details=${encodeURIComponent(details)}` +
                  `&location=${encodeURIComponent(location)}`;
                window.open(url, "_blank");
              }}>
                <img src="https://ssl.gstatic.com/calendar/images/dynamiclogo_2020q4/calendar_31_2x.png" className="w-4 h-4 mr-2 object-contain" alt="" />
                Google Calendar
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => window.open(`${API}/bookings/${booking.id}/ics`, "_blank")}>
                <Download className="w-4 h-4 mr-2" />
                Apple Calendar (.ics)
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </Layout>
  );
}

