337	  game: MyGame;
338	  onBack: () => void;
339	}) {
340	  const { user } = useUser();
341	  const { toast } = useToast();
342	  const qc = useQueryClient();
343	  const [text, setText] = useState("");
344	  const scrollRef = useRef<HTMLDivElement>(null);
345	
346	  const { data: messages, isLoading } = useQuery<GameChatMsg[]>({
347	    queryKey: ["game-chat", game.id],
348	    queryFn: () => customFetch<GameChatMsg[]>(`${API}/games/${game.id}/chat`),
349	    refetchInterval: 8000,
350	  });
351	
352	  useEffect(() => {
353	    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
354	  }, [messages]);
355	
356	  const send = useMutation({
357	    mutationFn: () => customFetch(`${API}/games/${game.id}/chat`, {
358	      method: "POST", headers: { "Content-Type": "application/json" },
359	      body: JSON.stringify({
360	        senderName: user?.fullName || user?.firstName || "Vartotojas",
361	        body: text.trim(),
362	      }),
363	    }),
364	    onSuccess: () => {
365	      setText("");
366	      qc.invalidateQueries({ queryKey: ["game-chat", game.id] });
367	    },
368	    onError: (e: any) => toast({ title: "Nepavyko siųsti", description: e?.message, variant: "destructive" }),
369	  });
370	
371	  const sportBg = sportColor[game.sport] ?? "#6b7280";
372	
373	  return (
374	    <div className="flex flex-col h-full min-h-0">
375	      <div className="border-b border-border shrink-0">
376	        <div className="p-3 flex items-center gap-2">
377	          <Button variant="ghost" size="icon" className="h-8 w-8 -ml-1" onClick={onBack} aria-label="Atgal">
378	            <ArrowLeft className="w-4 h-4"/>
379	          </Button>
380	          <div
381	            className="h-9 w-9 rounded-full flex items-center justify-center shrink-0 text-white"
382	            style={{ backgroundColor: sportBg }}
383	          >
384	            <SportIcon sport={game.sport} className="w-4 h-4" />
385	          </div>
386	          <div className="min-w-0 flex-1">
387	            <div className="font-semibold text-sm truncate">
388	              {sportLabel(game.sport)} · {game.placeName ?? game.city}
389	            </div>
390	            <div className="text-[11px] text-muted-foreground flex items-center gap-1">
391	              <UsersIcon className="w-3 h-3" />
392	              {game.participants.length}/{game.playersNeeded} dalyvių
393	            </div>
394	          </div>
395	        </div>
396	        <Link
397	          href={`/matches/${game.id}`}
398	          className="block px-3 pb-2 -mt-1"
399	        >
400	          <div className="inline-flex items-center gap-1.5 text-[11px] font-medium bg-primary/10 text-primary px-2 py-1 rounded-md hover:bg-primary/15 transition-colors max-w-full">
401	            <CalendarDays className="w-3 h-3 shrink-0" />
402	            <span className="truncate">{formatGameWhen(game.datetime)}</span>
403	            <ExternalLink className="w-3 h-3 shrink-0 opacity-70" />
404	          </div>
405	        </Link>
406	      </div>
407	
408	      <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 space-y-2 min-h-0">
409	        {isLoading ? (
410	          <div className="space-y-2">
411	            <Skeleton className="h-10 w-2/3"/>
412	            <Skeleton className="h-10 w-1/2 ml-auto"/>
413	          </div>
414	        ) : (messages ?? []).length === 0 ? (
415	          <div className="text-center py-10 text-muted-foreground">
416	            <MessageSquare className="w-8 h-8 mx-auto mb-2 opacity-50"/>
417	            <p className="text-xs">Dar nėra žinučių. Pradėkite pokalbį!</p>
418	          </div>
419	        ) : (
420	          (messages ?? []).map((m) => {
421	            const isMine = m.senderUserId === user?.id;
422	            return (
423	              <div key={m.id} className={`flex ${isMine ? "justify-end" : "justify-start"}`}>
424	                <div className={`max-w-[78%] rounded-2xl px-3 py-2 ${
425	                  isMine
426	                    ? "bg-primary text-primary-foreground rounded-br-md"
427	                    : "bg-muted rounded-bl-md"
428	                }`}>
429	                  {!isMine && (
430	                    <div className="text-[10px] font-semibold text-muted-foreground mb-0.5">
431	                      {m.senderName}
432	                    </div>
433	                  )}
434	                  <p className="text-sm whitespace-pre-wrap break-words">{m.body}</p>
435	                  <div className={`text-[10px] mt-0.5 ${isMine ? "text-primary-foreground/70" : "text-muted-foreground"}`}>
436	                    {timeAgo(m.createdAt)}
437	                  </div>
438	                </div>
439	              </div>
440	            );
441	          })
442	        )}
443	      </div>
444	
445	      <form
446	        className="border-t border-border p-2 flex items-center gap-2 shrink-0"
447	        onSubmit={(e) => { e.preventDefault(); if (text.trim() && !send.isPending) send.mutate(); }}
448	      >
449	        <Input
450	          placeholder="Parašykite žinutę grupei..."
451	          value={text}
452	          onChange={(e) => setText(e.target.value)}
453	          className="flex-1 h-9"
454	          autoFocus
455	        />
456	        <Button type="submit" size="icon" className="h-9 w-9 shrink-0" disabled={!text.trim() || send.isPending}>
457	          <Send className="w-4 h-4"/>
458	        </Button>
459	      </form>
460	    </div>
461	  );
462	}
