599	function ChatBubbleInner() {
600	  const { user } = useUser();
601	  const [open, setOpen] = useState(false);
602	  const [tab, setTab] = useState<"people" | "games">("people");
603	  const [active, setActive] = useState<{ userId: string; userName: string; imageUrl?: string | null; ctxType?: string; ctxId?: number } | null>(null);
604	  const [activeGame, setActiveGame] = useState<MyGame | null>(null);
605	
606	  const { data: threads, isLoading: threadsLoading } = useQuery<Thread[]>({
607	    queryKey: ["dm-threads"],
608	    queryFn: () => customFetch<Thread[]>(`${API}/dm/threads`),
609	    enabled: !!user,
610	    refetchInterval: 15000,
611	  });
612	
613	  const { data: myGames, isLoading: gamesLoading } = useQuery<MyGame[]>({
614	    queryKey: ["my-games-chat"],
615	    queryFn: () => customFetch<MyGame[]>(`${API}/games/my`),
616	    enabled: !!user && open,
617	    refetchInterval: 30000,
618	  });
619	
620	  const { data: unread } = useQuery<{ count: number }>({
621	    queryKey: ["dm-unread"],
622	    queryFn: () => customFetch<{ count: number }>(`${API}/dm/unread-count`),
623	    enabled: !!user,
624	    refetchInterval: 15000,
625	  });
626	
627	  const unreadCount = unread?.count ?? 0;
628	
629	  // Detect increases in unread count → play chime + browser notification
630	  const prevUnreadRef = useRef<number | null>(null);
631	  useEffect(() => {
632	    const prev = prevUnreadRef.current;
633	    if (prev !== null && unreadCount > prev) {
634	      playChime();
635	      // Pick latest unread thread for preview text
636	      const latest = threads?.find(t => t.unread > 0);
637	      if (latest) {
638	        showBrowserNotification(
639	          `${latest.otherUserName} · Nauja žinutė`,
640	          latest.lastMessage.body.slice(0, 140),
641	        );
642	      } else {
643	        showBrowserNotification("Nauja žinutė", "Atidarykite korts.lt, kad atsakytumėte.");
644	      }
645	    }
646	    prevUnreadRef.current = unreadCount;
647	  }, [unreadCount, threads]);
648	
649	  // Ask for notification permission the first time the user opens the bubble
650	  const askedPermRef = useRef(false);
651	  useEffect(() => {
652	    if (open && !askedPermRef.current) {
653	      askedPermRef.current = true;
654	      requestNotificationPermission();
655	    }
656	  }, [open]);
657	
658	  // Listen for global "open chat" events dispatched from other pages
659	  useEffect(() => {
660	    const handler = (e: Event) => {
661	      const ev = e as CustomEvent<OpenChatDetail>;
662	      if (!ev.detail?.userId) return;
663	      setActive({
664	        userId: ev.detail.userId,
665	        userName: ev.detail.userName,
666	        ctxType: ev.detail.ctxType,
667	        ctxId: ev.detail.ctxId,
668	      });
669	      setOpen(true);
670	    };
671	    window.addEventListener("korts:open-chat", handler);
672	    return () => window.removeEventListener("korts:open-chat", handler);
673	  }, []);
674	
675	  // Close on Escape
676	  useEffect(() => {
677	    if (!open) return;
678	    const onKey = (e: KeyboardEvent) => {
679	      if (e.key === "Escape") {
680	        if (active) setActive(null);
681	        else if (activeGame) setActiveGame(null);
682	        else setOpen(false);
683	      }
684	    };
685	    window.addEventListener("keydown", onKey);
686	    return () => window.removeEventListener("keydown", onKey);
687	  }, [open, active, activeGame]);
688	
689	  const toggle = useCallback(() => {
690	    setOpen(v => {
691	      if (v) {
692	        setActive(null);
693	        setActiveGame(null);
694	      }
695	      return !v;
696	    });
697	  }, []);
698	
699	  return (
700	    <>
701	      {/* Sticky bubble button */}
702	      <button
703	        onClick={toggle}
704	        aria-label={open ? "Uždaryti žinutes" : "Atidaryti žinutes"}
705	        className="fixed bottom-[5.5rem] right-4 sm:bottom-6 sm:right-6 z-[60] h-14 w-14 rounded-full bg-primary text-primary-foreground shadow-lg hover:shadow-xl hover:scale-105 active:scale-95 transition-all flex items-center justify-center focus:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2"
706	      >
707	        {open ? <X className="w-6 h-6"/> : <MessageCircle className="w-6 h-6"/>}
708	        {!open && unreadCount > 0 && (
709	          <span className="absolute -top-1 -right-1 min-w-5 h-5 px-1.5 rounded-full bg-red-500 text-white text-[11px] font-bold flex items-center justify-center shadow-md ring-2 ring-background">
710	            {unreadCount > 99 ? "99+" : unreadCount}
711	          </span>
712	        )}
713	      </button>
714	
715	      {/* Chat panel */}
716	      {open && (
717	        <div
718	          className="fixed z-[59] bg-card border border-border shadow-2xl overflow-hidden flex flex-col
719	            bottom-0 right-0 left-0 top-0 rounded-none
720	            sm:bottom-24 sm:right-6 sm:left-auto sm:top-auto sm:rounded-2xl sm:w-[380px] sm:h-[560px] sm:max-h-[calc(100dvh-8rem)]"
721	          role="dialog"
722	          aria-label="Žinutės"
723	        >
724	          <div className="border-b border-border p-3 flex items-center justify-between shrink-0 bg-primary/5">
725	            {active || activeGame ? (
726	              <div className="flex items-center gap-2 min-w-0">
727	                <MessageCircle className="w-4 h-4 text-primary shrink-0"/>
728	                <span className="font-semibold text-sm truncate">Pokalbis</span>
729	              </div>
730	            ) : (
731	              <div className="flex items-center gap-2">
732	                <MessageCircle className="w-4 h-4 text-primary"/>
733	                <span className="font-semibold text-sm">Žinutės</span>
734	                {unreadCount > 0 && (
735	                  <Badge className="h-5 min-w-5 px-1.5 bg-red-500 hover:bg-red-500 text-white">{unreadCount}</Badge>
736	                )}
737	              </div>
738	            )}
739	            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => setOpen(false)} aria-label="Uždaryti">
740	              <X className="w-4 h-4"/>
741	            </Button>
742	          </div>
743	
744	          {active ? (
745	            <ChatThreadView
746	              otherUserId={active.userId}
747	              otherUserName={active.userName}
748	              otherUserImageUrl={active.imageUrl}
749	              ctxType={active.ctxType}
750	              ctxId={active.ctxId}
751	              onBack={() => setActive(null)}
752	            />
753	          ) : activeGame ? (
754	            <GameChatView
755	              game={activeGame}
756	              onBack={() => setActiveGame(null)}
757	            />
758	          ) : (
759	            <>
760	              <div className="border-b border-border flex shrink-0 bg-card">
761	                <button
762	                  onClick={() => setTab("people")}
763	                  className={`flex-1 py-2.5 text-xs font-semibold transition-colors flex items-center justify-center gap-1.5 ${
764	                    tab === "people"
765	                      ? "text-primary border-b-2 border-primary"
766	                      : "text-muted-foreground hover:text-foreground border-b-2 border-transparent"
767	                  }`}
768	                >
769	                  <MessageSquare className="w-3.5 h-3.5"/> Žmonės
770	                  {unreadCount > 0 && (
771	                    <Badge className="h-4 min-w-4 px-1 ml-0.5 bg-red-500 hover:bg-red-500 text-white text-[10px]">{unreadCount}</Badge>
772	                  )}
773	                </button>
774	                <button
775	                  onClick={() => setTab("games")}
776	                  className={`flex-1 py-2.5 text-xs font-semibold transition-colors flex items-center justify-center gap-1.5 ${
777	                    tab === "games"
778	                      ? "text-primary border-b-2 border-primary"
779	                      : "text-muted-foreground hover:text-foreground border-b-2 border-transparent"
780	                  }`}
781	                >
782	                  <UsersIcon className="w-3.5 h-3.5"/> Žaidimai
783	                </button>
784	              </div>
785	              {tab === "people" ? (
786	                <ChatThreadsList
787	                  threads={threads}
788	                  isLoading={threadsLoading}
789	                  currentUserId={user?.id}
790	                  onPick={(t) => setActive({ userId: t.otherUserId, userName: t.otherUserName, imageUrl: t.otherUserImageUrl })}
791	                />
792	              ) : (
793	                <GameThreadsList
794	                  games={myGames}
795	                  isLoading={gamesLoading}
796	                  onPick={(g) => setActiveGame(g)}
797	                />
798	              )}
799	            </>
800	          )}
801	        </div>
802	      )}
803	    </>
804	  );
805	}
806	
807	export function ChatBubble() {
808	  return (
809	    <Show when="signed-in">
810	      <ChatBubbleInner />
811	    </Show>
812	  );
813	}
