  fetch(`${API}/courts/${cid}`)
    .then(r => r.ok ? r.json() : null)
    .then((c: any) => {
      if (c?.ownerUserId) setCourtOwner({ userId: c.ownerUserId, name: c.ownerName || "Savininkas" });
    })
    .catch(() => {});
}, [splitInfo?.courtId, booking?.courtId]);

